// Whitelist explicita (regra permanente do projeto): a RPC ja devolve so
// o necessario, mas reconstruimos aqui campo a campo mesmo assim -- nunca
// passthrough direto do jsonb da RPC, mesmo quando parece seguro hoje.
const row = $input.first()?.json?.resultado || {};
const carrinho = row.carrinho || { vazio: true, itens: [], valor_total: 0 };
return [{ json: {
  autorizado: !!row.autorizado,
  aguardando_confirmacao: !!row.aguardando_confirmacao,
  motivo: row.motivo || null,
  operacao: row.operacao,
  produto_id: row.produto_id,
  produto_nome: row.produto_nome,
  quantidade_antes: row.quantidade_antes,
  quantidade_final: row.quantidade_final,
  carrinho: {
    vazio: carrinho.itens ? carrinho.itens.length === 0 : true,
    itens: (carrinho.itens || []).map(i => ({
      produto_id: i.produto_id, nome: i.nome, quantidade: i.quantidade,
      preco_unitario: i.preco_unitario, subtotal: i.subtotal,
    })),
    valor_total: carrinho.valor_total,
  },
} }];
